import{_ as m,l as o,o as u,b,d as t,f as l,m as n,q as r}from"./chunks/framework.Tf23FRXt.js";const O="/assets/220.elcSNxF-.png",x=JSON.parse('{"title":"影之国","description":"","frontmatter":{},"headers":[{"level":2,"title":"BOSS 1 虚空死亡凝视","slug":"boss-1-虚空死亡凝视","link":"#boss-1-虚空死亡凝视","children":[]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 虚空弗迪亚","slug":"boss-2-虚空弗迪亚","link":"#boss-2-虚空弗迪亚","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 斯卡哈","slug":"boss-3-斯卡哈","link":"#boss-3-斯卡哈","children":[]},{"level":3,"title":"BOSS 4 迪亚波罗斯","slug":"boss-4-迪亚波罗斯","link":"#boss-4-迪亚波罗斯","children":[]}]},{"level":2,"title":"其他参考攻略","slug":"其他参考攻略","link":"#其他参考攻略","children":[]}],"relativePath":"duty/220.htm.md","filePath":"duty/220.md","lastUpdated":1791098838000}'),B={name:"duty/220.htm.md"};function a(k,s,T,g,f,v){const i=o("Status"),S=o("Role"),e=o("action"),p=o("quest"),d=o("item");return u(),b("div",null,[s[18]||(s[18]=t("h1",{id:"影之国",tabindex:"-1"},"影之国",-1)),s[19]||(s[19]=t("h2",{id:"boss-1-虚空死亡凝视",tabindex:"-1"},"BOSS 1 虚空死亡凝视",-1)),s[20]||(s[20]=t("p",null,"长方形场地前后（船头船尾）是安全的，两侧会掉下去（有 BOSS 的方向）。",-1)),s[21]||(s[21]=t("p",null,[l("BOSS 读条"),t("mark",null,"虚空即死"),l("，同时场中央会出现红黑色的圈，把玩家往中间吸，所有人要尽全力向外跑，一共会吸 2 次，第二次吸完立刻判定，所以第一次跑慢的人就跑不出去了。")],-1)),s[22]||(s[22]=t("p",null,[l("读条"),t("mark",null,"虚空暴风"),l("同时场地中央出现旋风圈，所有玩家站在旋风边上，判定时旋风内的玩家即死，其余玩家被吹飞，要保证自己能被吹到船头船尾，否则就会掉下去。")],-1)),s[23]||(s[23]=t("p",null,"虚空冰澈 + 虚空飙风，场地上出现距离衰减提示，玩家需要向距离衰减的落点对侧方向移动（比如衰减落点在左舷，那么玩家需要去到对应方向右舷位置），落点会落下大冰块，冰块落下后 BOSS 会开始读条吹风，需要让冰块挡住玩家，否则就掉下去了。",-1)),t("p",null,[s[0]||(s[0]=l("其他的出啥打啥有啥躲啥，BOSS 读条",-1)),s[1]||(s[1]=t("mark",null,"死亡宣告",-1)),s[2]||(s[2]=l("会随机点名 2 名玩家上",-1)),n(i,{id:910,name:"死亡宣告",dispel:""}),s[3]||(s[3]=l("，需要",-1)),n(S,{name:"healer"}),s[4]||(s[4]=l("治疗驱散（诗人也可以用",-1)),n(e,{name:"光阴神的礼赞凯歌"}),s[5]||(s[5]=l("驱散）。场地上会逐块变黑，当场地全部变黑并最后一次判定虚空极死时就是团灭。",-1))]),s[24]||(s[24]=r('<h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>路上会遇到两次<strong>虚无结晶</strong>，需要在结晶读条结束之前击杀，否则会出现妖异。第二次会搭配冥鬼的石化视线，注意背对。</p><h3 id="boss-2-虚空弗迪亚" tabindex="-1">BOSS 2 虚空弗迪亚</h3><div class="guide cols2"><div class="guide col"><img src="'+O+'"><p>蓝色阿托莫斯连线环，黄色阿托莫斯连线球。无连线的蓝色阿托莫斯脚下安全。</p></div><div class="guide col grow"><p>核心机制 1<mark> 虫洞</mark>，BOSS 会放出若干个阿托莫斯（场边的怪），并且有跟它连线的球或环。球或环表示近身 AOE（远离安全）或周身 AOE（脚下安全），而实际 AOE 出现的位置是没有连线的同色阿托莫斯。因此如果有环，则先看与环连线的阿托莫斯颜色，然后去没有连线的同色阿托莫斯脚下；如果没有环，远离没有连线的阿托莫斯；如果两个都是环，随便去哪个没连线的脚下。</p></div></div>',4)),t("p",null,[s[6]||(s[6]=l("核心机制 2，",-1)),s[7]||(s[7]=t("mark",null,"弱点生成",-1)),s[8]||(s[8]=l("，所有玩家会获得",-1)),n(i,{id:1137,name:"火属性耐性大幅降低"}),s[9]||(s[9]=l("或者",-1)),n(i,{id:1157,name:"水属性耐性大幅降低"}),s[10]||(s[10]=l("，同时场地上出现水 / 火的机关，需要把机关踩成与自己耐性相反的属性：如果是火耐性降低，那么需要把所有机关都踩成水；如果是水耐性降低，则需要都踩成火。远位通常由远程负责，近战注意打身位的时候不要反复踩机关。AOE 伤害与机关错误数量成正比，如果错的太多就会团灭。",-1))]),s[25]||(s[25]=t("p",null,"其他的出啥躲啥有啥打啥。",-1)),s[26]||(s[26]=t("h2",{id:"boss-2-boss-3",tabindex:"-1"},"BOSS 2 ~ BOSS 3",-1)),t("p",null,[s[11]||(s[11]=l("沿途中会有一只",-1)),s[12]||(s[12]=t("strong",null,"究极神兵原型",-1)),s[13]||(s[13]=l("，田园郡会有任务",-1)),n(p,{name:"不明飞行物"}),s[14]||(s[14]=l("，接任务打到这个怪之后回去交任务，可以获得",-1)),n(d,{name:"究极神兵原型装甲片"}),s[15]||(s[15]=l("，用于兑换饰品和衣服。",-1))]),s[27]||(s[27]=r('<p>这只究极神兵本身很好打，注意优先击杀各种小怪，有连线时神兵无敌，在神兵最后读条<mark>空间错乱</mark>时可以使用 LB 击杀。</p><h3 id="boss-3-斯卡哈" tabindex="-1">BOSS 3 斯卡哈</h3><p>BOSS 伸出两条丝带并读条<mark>阴影回旋</mark>时，注意向没有丝带的方向躲避。</p><p>有两个比较难躲的技能：<mark>阴影重击</mark>读条后会随机跳跃一个地方，不要追，会立刻有近身范围 AOE。 <mark>阴影直刺</mark>随机点名一名玩家放直线 AOE，注意看面相躲避。</p><p>手形小怪会随机连线 2 名玩家，只要面对小怪（连线变为白色），小怪就会停止移动，其他玩家趁此机会击杀。如果连线玩家背对小怪，小怪就会不断接近玩家，撞上之后玩家即死。</p>',5)),t("p",null,[s[16]||(s[16]=l("场地变红的时候不要移动，否则会中 debuff",-1)),n(i,{id:1790,name:"影之脚镣"}),s[17]||(s[17]=l("，移动速度大幅降低，很难躲避后续机制。",-1))]),s[28]||(s[28]=r('<p>当出现距离衰减 AOE 时，MT 带 BOSS 远离落点，落点会出现小怪<strong>康拉</strong>，需要有一名 T 拉住康拉，远离 BOSS，其他人转火击杀（康拉与 BOSS 距离过近会给 BOSS 上增强 buff，非常危险）。</p><p>被红黑色大饼点名，同时周身出现黑圈的玩家，需要带球向后场躲避（其他人注意避让），这个技能范围极大，伤害也比较高，要注意。</p><p>场地上出现图腾时注意需要有人去踩（图腾边缘发光证明踩上了），中央的大图腾伤害比较高，建议由 T 去踩，但无论如何每个图腾里都必须有人，否则极易团灭。</p><h3 id="boss-4-迪亚波罗斯" tabindex="-1">BOSS 4 迪亚波罗斯</h3><p>分为两段，基本上出啥躲啥，场地上会召唤门，注意及时转火打掉。</p><p>后半段和斯卡哈很像，<mark>暗影直刺</mark>是无范围预警直线 AOE，同时还有大饼追踪点名（这次是 3 个人），也需要踩图腾。</p><p>需要注意的是紫色带眼睛标记的分摊，需要玩家帮助分摊的同时背对，所以被点名的玩家注意不要太过靠近人群，防止误伤友军。</p><p>后半段场中央会出现一个带特效的门，这个门不可打掉，需要进去把里面的怪打掉（进去一个队就行，外面还有其他门需要打）。</p><p>最后一个团灭点是场地上会出现红色的晶球，要么大家都躲开（但基本不太可能），要么去把球撞掉，撞球会产生一个中等范围的 AOE 伤害，而且比较疼，如果两三个球撞在一起就极有可能团灭，要注意。</p><h2 id="其他参考攻略" tabindex="-1">其他参考攻略</h2><ul><li><a href="https://www.bilibili.com/video/av18941431" target="_blank" rel="noreferrer">子言姐姐考据视频攻略</a></li><li><a href="https://www.ffxiv.cn/detail/article/270" target="_blank" rel="noreferrer">susu 攻略</a></li></ul>',11))])}const E=m(B,[["render",a]]);export{x as __pageData,E as default};
